function Wizard() {
  const navigate = useNavigate(); const [step, setStep] = useState(1); const [title, setTitle] = useState(""); const [text, setText] = useState(""); const [fileName, setFileName] = useState(""); const [profile, setProfile] = useState<PerfilSaida>("Iniciante"); const [format, setFormat] = useState<FormatoSaida>((sessionStorage.getItem("adaptai-format") as FormatoSaida) || "Flashcards"); const [niche, setNiche] = useState<Nicho>("Geral"); const [domain, setDomain] = useState<DominioConhecimento>("TI"); const [detail, setDetail] = useState<NivelDetalhe>("Didatico"); const [analogies, setAnalogies] = useState(true); const [micro, setMicro] = useState(true); const [loading, setLoading] = useState(false); const [progress, setProgress] = useState(0); const [error, setError] = useState("");
  function onFile(file?: File) { if (!file) return; setFileName(file.name); setTitle((current) => current || file.name.replace(/\.[^.]+$/, "")); const reader = new FileReader(); reader.onload = () => setText(String(reader.result ?? "")); reader.readAsText(file); }
  async function generate() {
    setLoading(true); setError(""); setProgress(5);
    const timer = window.setInterval(() => setProgress((current) => Math.min(current + 14, 93)), 320);
    try {
      await uploadDocumento(title, text, fileName || "texto-colado.md");
      const result = await criarAdaptacao({ titulo: title || "Novo material de estudo", texto: text, perfil_destinatario: profile, formato_saida: format, nicho_setor: niche, nivel_detalhe: detail, dominio_conhecimento: domain, incluir_analogias: analogies, incluir_microlearning: micro });
      setProgress(100); navigate(`/adaptacoes/${result.id}`);
    } catch (e) { setError(e instanceof Error ? e.message : "Não foi possível gerar. Tente novamente."); setLoading(false); }
    finally { window.clearInterval(timer); }
  }
  return <div className="enter"><PageTitle eyebrow="CRIE SEU MATERIAL" title="Nova adaptação" description="Três escolhas cuidadosas. Um material que faz sentido para você." />
    <div className="mx-auto max-w-4xl">
      <div className="mb-7 flex items-center">{["Sua fonte", "Personalização", "Revisão"].map((label, i) => <div key={label} className="flex flex-1 items-center last:flex-none"><div className="flex items-center gap-2"><span className={`grid size-8 place-items-center rounded-full text-xs font-bold ${step > i + 1 ? "bg-[#dcece3] text-[#397d68]" : step === i + 1 ? "bg-primary text-primary-foreground" : "bg-muted text-muted-foreground"}`}>{step > i + 1 ? <Check size={15} /> : i + 1}</span><span className={`hidden text-xs font-semibold sm:block ${step === i + 1 ? "text-foreground" : "text-muted-foreground"}`}>{label}</span></div>{i < 2 && <div className={`mx-3 h-px flex-1 ${step > i + 1 ? "bg-[#8fc7ae]" : "bg-border"}`} />}</div>)}</div>
      <Card className="p-5 md:p-8">
        {step === 1 && <div><p className="text-xs font-bold uppercase tracking-[.15em] text-[#397d68]">01 / SUA FONTE</p><h2 className="mt-2 text-2xl font-bold">Comece pelo material.</h2><p className="mt-1 text-sm text-muted-foreground">Envie um arquivo de texto ou cole um trecho. O conteúdo permanece neste navegador.</p>
          <label className="mt-6 flex cursor-pointer flex-col items-center rounded-2xl border-2 border-dashed border-[#b9cdbf] bg-[#f2f6f1] px-5 py-9 text-center transition hover:border-[#74ae8c] dark:bg-[#1b2a24]" data-testid="dropzone-document"><span className="grid size-12 place-items-center rounded-2xl bg-card text-[#397d68]"><CloudUpload size={22} /></span><span className="mt-3 text-sm font-bold">{fileName || "Clique para escolher ou arraste um arquivo"}</span><span className="mt-1 text-xs text-muted-foreground">PDF, Markdown ou texto simples</span><input type="file" accept=".pdf,.md,.markdown,.txt,text/plain,text/markdown,application/pdf" onChange={(e) => onFile(e.target.files?.[0])} className="sr-only" data-testid="input-document-file" /></label>
          <div className="my-5 flex items-center gap-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border" />OU COLE O TEXTO<span className="h-px flex-1 bg-border" /></div>
          <Field label="Título do documento"><input value={title} onChange={(e) => setTitle(e.target.value)} className="rounded-xl border border-input bg-background px-4 py-3 outline-none focus:ring-2 focus:ring-ring" placeholder="Ex.: Fundamentos de VCN na OCI" data-testid="input-document-title" /></Field>
          <Field label="Conteúdo" hint="Para esta demonstração, arquivos PDF são identificados pelo nome; cole o texto para usar o conteúdo no material."><textarea value={text} onChange={(e) => setText(e.target.value)} rows={7} className="resize-y rounded-xl border border-input bg-background px-4 py-3 text-sm leading-6 outline-none focus:ring-2 focus:ring-ring" placeholder="Cole aqui a documentação, anotações ou um trecho técnico..." data-testid="input-document-text" /></Field>
          <div className="mt-6 flex justify-end"><Button onClick={() => { if (!text.trim()) setError("Cole o conteúdo ou escolha um arquivo de texto."); else { setError(""); setStep(2); } }} testId="button-wizard-next-1">Continuar <ArrowRight size={16} /></Button></div>
        </div>}
        {step === 2 && <div><p className="text-xs font-bold uppercase tracking-[.15em] text-[#397d68]">02 / PERSONALIZAÇÃO</p><h2 className="mt-2 text-2xl font-bold">Para quem estamos explicando?</h2><p className="mt-1 text-sm text-muted-foreground">Escolha o ponto de vista. Você pode ajustar depois.</p>
          <div className="mt-6"><p className="mb-2 text-sm font-semibold">Perfil de quem vai estudar</p><div className="flex flex-wrap gap-2">{profiles.map((item) => <button key={item} onClick={() => setProfile(item)} data-testid={`button-profile-${item}`} className={`rounded-full border px-3.5 py-2 text-xs font-semibold ${profile === item ? "border-primary bg-primary text-primary-foreground" : "border-border hover:bg-muted"}`}>{display(item)}</button>)}</div></div>
          <p className="mb-2 mt-6 text-sm font-semibold">Formato de saída</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-5">{formats.map(({ name, icon: Icon, caption }) => <button key={name} onClick={() => setFormat(name)} data-testid={`button-wizard-format-${name.replaceAll(" ", "-")}`} className={`rounded-xl border p-3 text-left ${format === name ? "border-[#76b89a] bg-[#e9f2ed] dark:bg-[#203a30]" : "border-border bg-background hover:bg-muted"}`}><Icon size={17} className={format === name ? "text-[#397d68]" : "text-muted-foreground"} /><p className="mt-2 text-xs font-bold">{name}</p><p className="mt-1 text-[10px] text-muted-foreground">{caption}</p></button>)}</div>
          <div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Nicho ou setor"><Select value={niche} onChange={(x) => setNiche(x as Nicho)} options={niches} testId="select-niche" /></Field><Field label="Domínio de conhecimento"><Select value={domain} onChange={(x) => setDomain(x as DominioConhecimento)} options={["Geral", "TI", "Medicina", "Financas", "Juridico", "Engenharia", "Educacao"]} testId="select-domain" /></Field></div>
          <div className="mt-5"><p className="mb-2 text-sm font-semibold">Profundidade</p><div className="grid grid-cols-3 rounded-xl bg-muted p-1">{details.map((item) => <button key={item} onClick={() => setDetail(item)} data-testid={`button-detail-${item}`} className={`rounded-lg py-2 text-xs font-semibold ${detail === item ? "bg-card text-foreground shadow-sm" : "text-muted-foreground"}`}>{display(item)}</button>)}</div></div>
          <div className="mt-5 grid gap-3 sm:grid-cols-2">{[
            { checked: analogies, setChecked: setAnalogies, label: "Incluir analogias", sub: "Criar pontes com o que você já conhece." },
            { checked: micro, setChecked: setMicro, label: "Incluir microlearning", sub: "Adicionar um exercício rápido ao final." },
          ].map(({ checked, setChecked, label, sub }) => <button key={label} onClick={() => setChecked(!checked)} data-testid={`toggle-${label.toLowerCase().replaceAll(" ", "-")}`} className="flex items-center gap-3 rounded-xl border border-border p-3 text-left"><span className={`grid size-5 place-items-center rounded-md ${checked ? "bg-[#397d68] text-white" : "border border-border"}`}>{checked && <Check size={13} />}</span><span><b className="block text-xs">{label}</b><small className="text-[10px] text-muted-foreground">{sub}</small></span></button>)}</div>
          <div className="mt-7 flex justify-between"><Button variant="quiet" onClick={() => setStep(1)} testId="button-wizard-back-2"><ArrowLeft size={16} /> Voltar</Button><Button onClick={() => setStep(3)} testId="button-wizard-next-2">Revisar <ArrowRight size={16} /></Button></div>
        </div>}
        {step === 3 && <div><p className="text-xs font-bold uppercase tracking-[.15em] text-[#397d68]">03 / REVISÃO</p><h2 className="mt-2 text-2xl font-bold">Tudo pronto para aprender.</h2><p className="mt-1 text-sm text-muted-foreground">Confira seu pacote antes de gerar. Nada é bloqueado pelo seu nível.</p>
          <div className="mt-6 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-muted/70 p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">DOCUMENTO</p><p className="mt-2 text-sm font-bold">{title || "Material sem título"}</p><p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{text.slice(0, 160)}</p></div><div className="rounded-xl bg-muted/70 p-4"><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">PACOTE DE ESTUDO</p><p className="mt-2 text-sm font-bold">{format} para {display(profile)}</p><p className="mt-1 text-xs text-muted-foreground">{display(niche)} · {display(detail)} · {display(domain)}</p></div></div>
          {loading && <div className="mt-6 rounded-xl border border-border p-4" role="status" data-testid="status-generation"><div className="flex items-center justify-between text-sm font-semibold"><span>{progress < 35 ? "Enviando documento..." : progress < 70 ? "Indexando conceitos e fontes..." : progress < 100 ? "Preparando seu material..." : "Material pronto"}</span><span className="font-mono text-xs">{progress}%</span></div><div className="mt-3 h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-[#76b89a] transition-all" style={{ width: `${progress}%` }} /></div></div>}
          {error && <div role="alert" data-testid="status-generation-error" className="mt-4 rounded-xl border border-destructive/30 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}
          <div className="mt-7 flex justify-between"><Button variant="quiet" disabled={loading} onClick={() => setStep(2)} testId="button-wizard-back-3"><ArrowLeft size={16} /> Ajustar</Button><Button disabled={loading} onClick={generate} testId="button-generate">{loading ? "Criando seu material..." : "Gerar adaptação"} {!loading && <Sparkles size={16} />}</Button></div>
        </div>}
      </Card>
    </div>
  </div>;
}

function AdaptationsList() {
  const [items, setItems] = useState<Adaptacao[]>([]); const [loading, setLoading] = useState(true); const [query, setQuery] = useState(""); const [format, setFormat] = useState("Todos"); const [niche, setNiche] = useState("Todos");
  useEffect(() => { listarAdaptacoes().then(setItems).finally(() => setLoading(false)); }, []);
  const filtered = useMemo(() => items.filter((item) => item.titulo.toLowerCase().includes(query.toLowerCase()) && (format === "Todos" || item.formato_saida === format) && (niche === "Todos" || item.nicho_setor === niche)), [items, query, format, niche]);
  return <div className="enter"><PageTitle eyebrow="SUA BIBLIOTECA" title="Minhas adaptações" description="Todo material que você já transformou em aprendizado." action={<Button href="/nova-adaptacao" testId="button-create-from-list"><Plus size={16} /> Nova adaptação</Button>} />
    <Card className="mb-5"><div className="grid gap-3 sm:grid-cols-[1fr_190px_190px]"><label className="flex items-center gap-2 rounded-xl border border-input px-3"><Search size={16} className="text-muted-foreground" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Buscar por título..." className="w-full bg-transparent py-3 text-sm outline-none" data-testid="input-adaptation-search" /></label><Select value={format} onChange={setFormat} options={["Todos", ...formats.map((f) => f.name)]} testId="filter-format" /><Select value={niche} onChange={setNiche} options={["Todos", ...niches]} testId="filter-niche" /></div></Card>
    {loading ? <div className="grid gap-3">{[1, 2, 3].map((i) => <div key={i} className="h-[96px] animate-pulse rounded-2xl bg-muted" />)}</div> : filtered.length ? <div className="grid gap-3">{filtered.map((item) => <AdaptationRow key={item.id} item={item} />)}</div> : <Card className="py-14 text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-[#e5f0e9] text-[#397d68] dark:bg-[#203a30]"><Search size={22} /></span><h2 className="mt-4 text-xl font-bold">{items.length ? "Nenhum resultado por aqui." : "Sua biblioteca começa com uma fonte."}</h2><p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">{items.length ? "Tente ajustar sua busca ou seus filtros." : "Crie seu primeiro material personalizado e encontre-o aqui depois."}</p><Button href={items.length ? "/adaptacoes" : "/nova-adaptacao"} testId="button-empty-adaptations" className="mt-5">{items.length ? "Limpar filtros" : "Criar primeira adaptação"} <ArrowRight size={15} /></Button></Card>}
  </div>;
}

function Documents() {
  const [docs, setDocs] = useState<{ id: string; titulo: string; formato: string; status: string; criado_em: string }[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  function load() { setLoading(true); setError(""); listarDocumentos().then(setDocs).catch(() => setError("Não foi possível carregar seus documentos.")).finally(() => setLoading(false)); }
  useEffect(() => { load(); }, []);
  return <div className="enter"><PageTitle eyebrow="SUAS FONTES" title="Documentos" description="As fontes que deram origem aos seus materiais de estudo." action={<Button href="/nova-adaptacao" testId="button-add-document"><Plus size={16} /> Adicionar documento</Button>} />
    {loading ? <div className="grid gap-3">{[1, 2].map((i) => <div key={i} className="h-20 animate-pulse rounded-2xl bg-muted" />)}</div> : error ? <Card className="py-12 text-center"><CircleHelp className="mx-auto text-muted-foreground" /><p className="mt-3">{error}</p><Button onClick={load} testId="button-retry-documents" className="mt-4">Tentar novamente</Button></Card> : docs.length ? <div className="grid gap-3">{docs.map((doc) => <Card key={doc.id} className="flex items-center gap-4"><span className="grid size-11 place-items-center rounded-xl bg-muted text-[#397d68]"><FileText size={19} /></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{doc.titulo}</p><p className="mt-1 text-xs text-muted-foreground">{doc.formato} · Adicionado {doc.criado_em}</p></div><Pill tone={doc.status === "concluido" ? "mint" : "amber"}>{doc.status === "concluido" ? "Concluído" : display(doc.status)}</Pill></Card>)}</div> : <Card className="py-14 text-center"><span className="mx-auto grid size-14 place-items-center rounded-2xl bg-muted"><FileText size={23} /></span><h2 className="mt-4 text-xl font-bold">Ainda não há documentos.</h2><p className="mt-2 text-sm text-muted-foreground">Envie uma fonte para começar seu primeiro material.</p><Button href="/nova-adaptacao" testId="button-documents-empty" className="mt-5">Adicionar fonte <ArrowRight size={15} /></Button></Card>}
  </div>;
}

function Trail() {
  const [data, setData] = useState<Awaited<ReturnType<typeof getPerfil>> | null>(null); const [loading, setLoading] = useState(true); const [domain, setDomain] = useState<DominioConhecimento>("TI"); const [test, setTest] = useState(false);
  useEffect(() => { getPerfil().then(setData).finally(() => setLoading(false)); }, []);
  return <div className="enter"><PageTitle eyebrow="PROGRESSO COM PROPÓSITO" title="Minha trilha" description="Um mapa do que você já domina e do que está começando a aprender." />
    {loading ? <div className="h-48 animate-pulse rounded-2xl bg-muted" /> : <>
      <Card className="mb-5 bg-[#e5f0e9] dark:bg-[#203a30]"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-wider text-[#397d68]">SUA JORNADA ATÉ AQUI</p><h2 className="mt-2 text-3xl font-bold">{data?.xp_total} XP</h2><p className="mt-1 text-sm text-muted-foreground">Nível atual: <b className="text-foreground">Praticante</b></p></div><div className="w-full max-w-md"><div className="flex justify-between text-xs text-muted-foreground"><span>Até o próximo marco</span><span>820 / 1.000 XP</span></div><div className="mt-2 h-2.5 rounded-full bg-white/60 dark:bg-black/20"><div className="h-full w-[82%] rounded-full bg-[#73b593]" /></div><p className="mt-2 text-xs text-muted-foreground">Faltam 180 XP. Seu tempo, suas regras.</p></div></div></Card>
      <div className="mb-5 flex items-center gap-3"><span className="text-sm font-semibold">Mostrar níveis para</span><Select value={domain} onChange={(x) => setDomain(x as DominioConhecimento)} options={["Geral", "TI", "Medicina", "Financas", "Juridico", "Engenharia", "Educacao"]} testId="select-trail-domain" /></div>
      <div className="relative grid gap-3">{levels.map((level, i) => <div key={level} className={`relative flex gap-4 rounded-2xl border p-4 ${i === 2 ? "border-[#83b99b] bg-[#f1f7f2] dark:bg-[#203a30]" : "border-border bg-card"}`}><div className="relative z-10 flex flex-col items-center"><span className={`grid size-10 place-items-center rounded-full ${i < 3 ? "bg-[#dcece3] text-[#397d68]" : "bg-muted text-muted-foreground"}`}>{i < 2 ? <Check size={17} /> : i === 2 ? <Flame size={17} /> : <span className="font-mono text-xs">0{i + 1}</span>}</span>{i < 4 && <span className="absolute top-10 h-[calc(100%+24px)] w-px bg-border" />}</div><div className="flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">{levelNames[i]}</p><h3 className="mt-1 text-lg font-bold">{getRotuloNivel(level, domain)}</h3></div>{i < 2 ? <Pill tone="mint">Concluído</Pill> : i === 2 ? <Pill tone="mint">Você está aqui</Pill> : <Pill>Próxima etapa</Pill>}</div><p className="mt-2 text-sm text-muted-foreground">{["Primeiros conceitos e fundamentos.", "Aplicação consistente do que você aprendeu.", "Conecte ideias e aprofunde seu repertório.", "Resolva desafios complexos com autonomia.", "Domínio amplo e pensamento original."][i]}</p></div></div>)}</div>
      <div className="mt-6 grid gap-5 lg:grid-cols-[1fr_.9fr]"><Card><div className="flex items-center justify-between"><h2 className="text-lg font-bold">Conceitos no seu radar</h2><Pill tone="mint">{data?.conceitos.length ?? 0} conceitos</Pill></div><div className="mt-4 grid gap-2">{data?.conceitos.map((concept) => <div key={concept.nome} className="flex items-center justify-between rounded-xl bg-muted/60 px-3 py-3"><span className="text-sm font-semibold">{concept.nome}</span><Pill tone={concept.status === "dominado" ? "mint" : "amber"}>{concept.status === "dominado" ? "Dominado" : "Em aprendizado"}</Pill></div>)}</div></Card>
        <Card className="border-[#e8d7ad] bg-[#fbf4e5] dark:border-[#5b4c2e] dark:bg-[#352e20]"><span className="grid size-10 place-items-center rounded-xl bg-[#f1e2bc] text-[#896b2e]"><Target size={19} /></span><Pill tone="amber" ><span className="mt-3 inline-block">DISPONÍVEL SE QUISER</span></Pill><h2 className="mt-3 text-xl font-bold">Teste de Nível</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Uma oportunidade de reconhecer o que você já aprendeu. Fazer agora, depois ou nunca — sua trilha continua.</p>
          {!test ? <Button variant="outline" onClick={() => setTest(true)} testId="button-start-level-test" className="mt-4">Ver sugestão de teste <ArrowRight size={15} /></Button> : <div role="status" data-testid="status-level-test" className="mt-4 rounded-xl bg-card p-3 text-sm"><p className="font-bold">Sugestão anotada.</p><p className="mt-1 text-muted-foreground">Esta demonstração não aplica uma avaliação, mas seu progresso segue normalmente.</p></div>}
          <p className="mt-3 text-xs font-semibold text-[#795d24]">Não bloqueia conteúdos. Nunca.</p></Card></div>
    </>}</div>;
}

function SourceDrawer({ chunk, onClose }: { chunk: { trecho: string; pagina: number; relevancia: number } | null; onClose: () => void }) {
  if (!chunk) return null;
  return <div className="fixed inset-0 z-50 flex justify-end bg-black/35" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}><aside role="dialog" aria-modal="true" aria-label="Trecho da fonte" className="enter h-full w-full max-w-md overflow-y-auto border-l border-border bg-card p-6 shadow-2xl"><div className="flex items-center justify-between"><div><Pill tone="mint"><ShieldCheck size={12} className="mr-1" /> FONTE ORIGINAL</Pill><h2 className="mt-3 text-xl font-bold">Trecho utilizado</h2></div><button onClick={onClose} data-testid="button-close-source" className="grid size-9 place-items-center rounded-xl hover:bg-muted" aria-label="Fechar fonte"><X size={18} /></button></div><div className="mt-7 rounded-xl border border-border bg-muted/50 p-5"><p className="text-sm leading-7">{chunk.trecho}</p><p className="mt-5 border-t border-border pt-3 text-xs text-muted-foreground">Documento técnico · Página {chunk.pagina}</p></div><div className="mt-4 flex justify-between text-sm"><span className="text-muted-foreground">Relevância do trecho</span><b>{Math.round(chunk.relevancia * 100)}%</b></div><p className="mt-6 text-xs leading-5 text-muted-foreground">Este trecho foi recuperado para ancorar a explicação. A fidelidade mostra o quanto o material se mantém próximo à documentação enviada.</p></aside></div>;
}

function Result() {
  const { id = "" } = useParams(); const [item, setItem] = useState<Adaptacao | null>(null); const [loading, setLoading] = useState(true); const [source, setSource] = useState<{ trecho: string; pagina: number; relevancia: number } | null>(null);
  const [index, setIndex] = useState(0); const [flipped, setFlipped] = useState(false); const [mastered, setMastered] = useState<string[]>([]); const [answers, setAnswers] = useState<Record<number, number>>({}); const [analogiesOpen, setAnalogiesOpen] = useState(false);
  useEffect(() => { setLoading(true); buscarAdaptacao(id).then((result) => setItem(result ?? null)).finally(() => setLoading(false)); }, [id]);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if (!item?.conteudo.flashcards?.length) return; if (event.key === "ArrowRight") setIndex((v) => (v + 1) % item.conteudo.flashcards!.length); if (event.key === "ArrowLeft") setIndex((v) => (v - 1 + item.conteudo.flashcards!.length) % item.conteudo.flashcards!.length); if (event.key === " " && (event.target as HTMLElement).tagName !== "BUTTON") { event.preventDefault(); setFlipped((v) => !v); } }; window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler); }, [item]);
  if (loading) return <div className="space-y-4"><div className="h-8 w-1/2 animate-pulse rounded-lg bg-muted" /><div className="h-64 animate-pulse rounded-2xl bg-muted" /></div>;
  if (!item) return <Card className="py-16 text-center"><h2 className="text-xl font-bold">Não encontramos essa adaptação.</h2><Button href="/adaptacoes" testId="button-back-library" className="mt-5"><ArrowLeft size={15} /> Voltar à biblioteca</Button></Card>;
  const chunks = item.fontes_chunks;
  function openSource(chunkId: string) { setSource(chunks.find((c) => c.id === chunkId) ?? chunks[0] ?? null); }
  const activeFlash = item.conteudo.flashcards?.[index];
  return <div className="enter"><Link to="/adaptacoes" className="mb-4 inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground" data-testid="link-back-adaptations"><ArrowLeft size={15} /> Minhas adaptações</Link>
    <div className="grid gap-5 xl:grid-cols-[1fr_290px]"><div className="min-w-0">
      <div className="mb-5"><div className="flex flex-wrap items-center gap-2"><Pill tone="dark">{item.formato_saida}</Pill><Pill tone="mint">{item.rotulo_perfil_aplicado}</Pill><Pill>{display(item.nicho_setor)}</Pill>{item.cache_hit && <Pill tone="amber">Cache</Pill>}<Pill tone="mint">Upload {display(item.status_upload)}</Pill></div><h1 className="mt-4 text-3xl font-bold md:text-4xl" data-testid="text-adaptation-title">{item.titulo}</h1><p className="mt-2 text-sm text-muted-foreground">{item.formato_saida} para {item.rotulo_perfil_aplicado} · {display(item.nicho_setor)} · {item.tempo_estimado} · Domínio {display(item.dominio_conhecimento)}</p></div>
      {item.alerta_descompasso && <div role="alert" data-testid="alert-mismatch" className="mb-5 flex gap-3 rounded-xl border border-[#e5d19c] bg-[#fbf4e5] p-4 text-sm dark:border-[#5b4c2e] dark:bg-[#352e20]"><Lightbulb className="shrink-0 text-[#9b762c]" size={18} /><div><b>Um ponto para conferir.</b><p className="mt-1 text-muted-foreground">O nível sugerido e o conteúdo da fonte podem não estar alinhados. Ajuste o perfil se fizer sentido — isso não impede seu estudo.</p></div></div>}
      <Card className="mb-5"><h2 className="text-sm font-bold uppercase tracking-wider text-muted-foreground">Conceitos-chave</h2><div className="mt-3 flex flex-wrap gap-2">{item.conceitos_chave.map((x) => <Pill key={x} tone="mint">{x}</Pill>)}</div><p className="mt-4 text-xs text-muted-foreground"><b className="text-foreground">Pré-requisitos:</b> {item.prerequisitos.join(" · ")}</p></Card>
      {item.conteudo.flashcards && activeFlash && <Card><div className="flex items-center justify-between"><div><Pill tone="mint">FLASHCARD {String(index + 1).padStart(2, "0")} / {item.conteudo.flashcards.length}</Pill><p className="mt-2 text-xs text-muted-foreground">Use ← → para navegar e espaço para virar.</p></div><span className="font-mono text-xs text-muted-foreground">{mastered.length} dominados</span></div>
        <button onClick={() => setFlipped(!flipped)} onKeyDown={(e) => { if (e.key === "Enter") setFlipped(!flipped); }} aria-label={flipped ? "Mostrar pergunta" : "Mostrar resposta"} data-testid="button-flashcard-flip" className="group mt-5 min-h-[260px] w-full rounded-2xl border border-[#c6ded1] bg-[#eaf3ed] p-6 text-left transition-all hover:border-[#82b899] dark:bg-[#203a30] sm:p-9"><div className="flex min-h-[210px] flex-col justify-center"><span className="text-[10px] font-bold uppercase tracking-[.17em] text-[#397d68]">{flipped ? "RESPOSTA" : "PERGUNTA"}</span><h2 className="mt-5 max-w-2xl text-2xl font-bold leading-snug md:text-3xl">{flipped ? activeFlash.resposta : activeFlash.pergunta}</h2>{flipped && <p className="mt-4 max-w-xl text-sm leading-6 text-muted-foreground">{activeFlash.dica_didatica}</p>}<span className="mt-7 inline-flex items-center gap-1.5 text-xs font-bold text-[#397d68]">Ver {flipped ? "pergunta" : "resposta"} <ArrowRight size={13} /></span></div></button>
        <div className="mt-4 flex flex-wrap items-center justify-between gap-3"><button onClick={() => { setIndex((index - 1 + item.conteudo.flashcards!.length) % item.conteudo.flashcards!.length); setFlipped(false); }} className="grid size-10 place-items-center rounded-xl border border-border" aria-label="Cartão anterior" data-testid="button-flashcard-prev"><ChevronLeft size={18} /></button><Button variant={mastered.includes(activeFlash.pergunta) ? "mint" : "outline"} onClick={() => setMastered((arr) => arr.includes(activeFlash.pergunta) ? arr.filter((x) => x !== activeFlash.pergunta) : [...arr, activeFlash.pergunta])} testId="button-mark-mastered"><Check size={16} /> {mastered.includes(activeFlash.pergunta) ? "Dominado" : "Marcar como dominado"}</Button><button onClick={() => { setIndex((index + 1) % item.conteudo.flashcards!.length); setFlipped(false); }} className="grid size-10 place-items-center rounded-xl border border-border" aria-label="Próximo cartão" data-testid="button-flashcard-next"><ChevronRight size={18} /></button></div>
        <button onClick={() => openSource(activeFlash.fonte_chunk_id)} data-testid="button-source-flashcard" className="mt-4 inline-flex items-center gap-2 text-xs font-semibold text-[#397d68]"><ShieldCheck size={14} /> Ver fonte · página {chunks.find((c) => c.id === activeFlash.fonte_chunk_id)?.pagina ?? 1}</button>
      </Card>}
      {item.conteudo.quiz && <div className="grid gap-4">{item.conteudo.quiz.map((question, i) => <Card key={question.pergunta}><Pill tone="dark">QUESTÃO {i + 1}</Pill><h2 className="mt-4 text-lg font-bold">{question.pergunta}</h2><div className="mt-4 grid gap-2">{question.opcoes.map((option, oi) => { const selected = answers[i] === oi; const done = answers[i] !== undefined; const correct = question.correta === oi; return <button key={option} onClick={() => !done && setAnswers({ ...answers, [i]: oi })} disabled={done} data-testid={`button-quiz-${i}-${oi}`} className={`rounded-xl border px-4 py-3 text-left text-sm ${done && correct ? "border-[#79b899] bg-[#e6f2ea] dark:bg-[#203a30]" : selected && !correct ? "border-destructive/40 bg-destructive/5" : "border-border hover:bg-muted"}`}>{option}</button>; })}</div>{answers[i] !== undefined && <div role="status" data-testid={`status-quiz-feedback-${i}`} className={`mt-4 rounded-xl p-3 text-sm ${answers[i] === question.correta ? "bg-[#e6f2ea] text-[#286349] dark:bg-[#203a30] dark:text-[#b4e2c8]" : "bg-[#fbf4e5] text-[#74591f] dark:bg-[#352e20]"}`}><b>{answers[i] === question.correta ? "Isso mesmo." : "Quase. Veja a fonte e tente de novo no próximo estudo."}</b><p className="mt-1">{question.explicacao}</p><button onClick={() => openSource(question.fonte_chunk_id)} data-testid={`button-quiz-source-${i}`} className="mt-2 inline-flex items-center gap-1 font-bold"><ShieldCheck size={13} /> Ver fonte</button></div>}</Card>)}</div>}
      {item.conteudo.resumo && <Card><Pill tone="mint">RESUMO</Pill><p className="mt-5 text-lg leading-8">{item.conteudo.resumo.abertura}</p><ul className="mt-5 grid gap-3">{item.conteudo.resumo.pontos.map((point, i) => <li key={point} className="flex gap-3 rounded-xl bg-muted/55 p-3 text-sm leading-6"><span className="grid size-6 shrink-0 place-items-center rounded-full bg-[#dcece3] text-xs font-bold text-[#397d68]">{i + 1}</span>{point}</li>)}</ul><p className="mt-5 border-l-2 border-[#76b89a] pl-4 text-sm font-semibold leading-6">{item.conteudo.resumo.conclusao}</p><SourceButton onClick={() => openSource(item.conteudo.resumo!.fonte_chunk_id)} /></Card>}
      {item.conteudo.tutorial && <Card><Pill tone="mint">TUTORIAL</Pill><p className="mt-5 text-lg leading-8">{item.conteudo.tutorial.introducao}</p><div className="mt-6 grid gap-4">{item.conteudo.tutorial.secoes.map((section, i) => <div key={section.titulo} className="rounded-xl border border-border p-4"><div className="flex items-start gap-3"><span className="grid size-7 shrink-0 place-items-center rounded-full bg-[#dcece3] text-xs font-bold text-[#397d68]">{i + 1}</span><div><h3 className="font-bold">{section.titulo}</h3><p className="mt-2 text-sm leading-7 text-muted-foreground">{section.conteudo}</p><SourceButton onClick={() => openSource(section.fonte_chunk_id)} /></div></div></div>)}</div></Card>}
      {item.conteudo.roteiro && <Card><div className="flex items-start justify-between"><div><Pill tone="mint">ROTEIRO DE AULA</Pill><h2 className="mt-3 text-xl font-bold">Uma aula com começo, meio e prática.</h2></div><Pill tone="dark">{item.conteudo.roteiro.duracao}</Pill></div><div className="mt-6 grid gap-3">{item.conteudo.roteiro.etapas.map((section) => <div key={section.titulo} className="flex gap-4 rounded-xl border border-border p-4"><span className="w-16 shrink-0 pt-1 font-mono text-xs font-bold text-[#397d68]">{section.tempo}</span><div><h3 className="font-bold">{section.titulo}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{section.descricao}</p><SourceButton onClick={() => openSource(section.fonte_chunk_id)} /></div></div>)}</div></Card>}
      {item.analogia && <Card className="mt-5"><button onClick={() => setAnalogiesOpen(!analogiesOpen)} aria-expanded={analogiesOpen} data-testid="button-toggle-analogy" className="flex w-full items-center justify-between text-left"><span className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-xl bg-[#f4ebd5] text-[#937029]"><Lightbulb size={17} /></span><span><b className="block text-sm">Analogias para aproximar</b><small className="text-xs text-muted-foreground">Compare conceitos técnicos com o cotidiano.</small></span></span><ChevronDown size={17} className={analogiesOpen ? "rotate-180" : ""} /></button>{analogiesOpen && <div className="mt-4 border-t border-border pt-4"><div className="grid gap-2">{item.analogia.mapeamento.map((map) => <div key={map.termo} className="flex items-center gap-3 rounded-lg bg-muted/50 p-3 text-sm"><b>{map.termo}</b><ArrowRight size={14} className="text-[#397d68]" /><span>{map.analogia}</span></div>)}</div><p className="mt-3 text-xs leading-5 text-muted-foreground"><b>Onde a comparação termina:</b> {item.analogia.limite_da_analogia}</p></div>}</Card>}
      {item.microlearning && <Card className="mt-5 border-[#e5d19c] bg-[#fbf4e5] dark:border-[#5b4c2e] dark:bg-[#352e20]"><Pill tone="amber">MICROLEARNING · {item.microlearning.minutos} MIN</Pill><p className="mt-3 text-sm font-semibold">{item.microlearning.tarefa}</p></Card>}
    </div>
    <aside className="grid content-start gap-4"><Card><div className="flex items-center gap-2"><ShieldCheck size={17} className="text-[#397d68]" /><h2 className="font-bold">Qualidade do material</h2></div><p className="mt-1 text-xs text-muted-foreground">Como esta adaptação foi construída.</p><Score label="Ancoragem na fonte" score={item.ancoragem_fonte_score} /><Score label="Fidelidade das analogias" score={item.fidelidade_analogias_score} /><Score label="Clareza pedagógica" score={item.clareza_pedagogica} /><div className="mt-4 flex justify-between border-t border-border pt-4 text-xs"><span className="text-muted-foreground">Trechos consultados</span><b>{item.chunks_utilizados}</b></div><div className="mt-2 flex justify-between text-xs"><span className="text-muted-foreground">Domínio de conhecimento</span><b>{display(item.dominio_conhecimento)}</b></div><div className="mt-4 flex flex-wrap gap-2"><Pill tone="mint">Busca híbrida</Pill>{item.cache_hit && <Pill tone="amber">Cache hit</Pill>}</div></Card>
      <Card><h3 className="text-sm font-bold">Sobre este pacote</h3><div className="mt-4 grid gap-3 text-xs"><Meta label="Perfil" value={item.rotulo_perfil_aplicado} /><Meta label="Formato" value={item.formato_saida} /><Meta label="Nicho" value={display(item.nicho_setor)} /><Meta label="Detalhe" value={display(item.nivel_detalhe)} /><Meta label="Upload ao bucket" value={display(item.status_upload)} /></div></Card>
    </aside></div><SourceDrawer chunk={source} onClose={() => setSource(null)} /></div>;
}
function SourceButton({ onClick }: { onClick: () => void }) { return <button onClick={onClick} data-testid="button-view-source" className="mt-3 inline-flex items-center gap-1.5 text-xs font-bold text-[#397d68]"><ShieldCheck size={13} /> Ver trecho da fonte</button>; }
function Meta({ label, value }: { label: string; value: string }) { return <div className="flex justify-between gap-3"><span className="text-muted-foreground">{label}</span><b className="text-right">{value}</b></div>; }
function Score({ label, score }: { label: string; score: number }) { return <div className="mt-5"><div className="flex justify-between text-xs"><span>{label}</span><b className="font-mono">{score}%</b></div><div className="mt-2 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-[#76b89a]" style={{ width: `${score}%` }} /></div></div>; }

function AppRoutes() {
  return <Routes>
    <Route path="/" element={<Landing />} />
    <Route path="/login" element={tokenStorage.get() ? <Navigate to="/painel" replace /> : <AuthPage mode="login" />} />
    <Route path="/cadastro" element={tokenStorage.get() ? <Navigate to="/painel" replace /> : <AuthPage mode="cadastro" />} />
    <Route path="/painel" element={<Protected><AppShell><Dashboard /></AppShell></Protected>} />
    <Route path="/nova-adaptacao" element={<Protected><AppShell><Wizard /></AppShell></Protected>} />
    <Route path="/adaptacoes" element={<Protected><AppShell><AdaptationsList /></AppShell></Protected>} />
    <Route path="/adaptacoes/:id" element={<Protected><AppShell><Result /></AppShell></Protected>} />
    <Route path="/documentos" element={<Protected><AppShell><Documents /></AppShell></Protected>} />
    <Route path="/trilha" element={<Protected><AppShell><Trail /></AppShell></Protected>} />
    <Route path="*" element={<main className="grid min-h-screen place-items-center bg-background p-6 text-center"><div><h1 className="text-3xl font-bold">Essa página não está na trilha.</h1><Button href="/" testId="button-not-found-home" className="mt-5">Voltar ao início</Button></div></main>} />
  </Routes>;
}
export default function App() { return <BrowserRouter><AppRoutes /></BrowserRouter>; }
